mapper.select:
select DATE_FORMAT(`stat_time`,#{format}) as `trendX`, CAST(avg(`pm_two_point_five`) as DECIMAL(15,2)) as `trendY`
from `environment_hour_stat`


        and `stat_time` >= #{period.begin}


        and `stat_time` <= #{period.end}


group by `trendX`

select CAST(avg(`pm_two_point_five`) as DECIMAL(15,2)) as `pmTwoPointFile`
from `environment_hour_stat`


        and `stat_time` >= #{param.period.begin}


        and `stat_time` <= #{param.period.end}
